                hiddenWorkflowCount > 0
                  ? `<p class="muted" style="margin:4px 0 0;">${escapeHtml(hiddenWorkflowCount)} developer/test workflow${hiddenWorkflowCount === 1 ? "" : "s"} hidden.</p>`
                  : ""
