const AION_WORKFLOW_DRAFT_STORAGE_KEY = "aion.workflow_builder.current_draft.v1";

const AION_WORKFLOW_GLYPH_SCHEMA_VERSION = "aion.workflow_glyph.v1";

function getAionWorkflowOrderedNodesForGlyph(graph) {
  const nodes = getAionWorkflowOrderedNodesForGlyph(graph);
  const edges = Array.isArray(graph?.edges) ? graph.edges : [];

  if (!nodes.length) return [];

  const nodeById = new Map(nodes.map((node) => [String(node.id), node]));
  const incoming = new Map(nodes.map((node) => [String(node.id), 0]));
  const outgoing = new Map(nodes.map((node) => [String(node.id), []]));

  for (const edge of edges) {
    const from = String(edge?.from || "");
    const to = String(edge?.to || "");

    if (!nodeById.has(from) || !nodeById.has(to)) continue;

    incoming.set(to, (incoming.get(to) || 0) + 1);
    outgoing.get(from)?.push(to);
  }

  const visualSort = (a, b) => {
    const ax = Number(a?.x || 0);
    const bx = Number(b?.x || 0);
    const ay = Number(a?.y || 0);
    const by = Number(b?.y || 0);

    if (ax !== bx) return ax - bx;
    if (ay !== by) return ay - by;
    return String(a?.id || "").localeCompare(String(b?.id || ""));
  };

  if (!edges.length) {
    return [...nodes].sort(visualSort);
  }

  const queue = nodes
    .filter((node) => (incoming.get(String(node.id)) || 0) === 0)
    .sort(visualSort);

  const ordered = [];
  const seen = new Set();

  while (queue.length) {
    const node = queue.shift();
    const nodeId = String(node.id);

    if (seen.has(nodeId)) continue;

    seen.add(nodeId);
    ordered.push(node);

    const nextIds = [...(outgoing.get(nodeId) || [])]
      .map((id) => nodeById.get(id))
      .filter(Boolean)
      .sort(visualSort);

    for (const nextNode of nextIds) {
      const nextId = String(nextNode.id);
      incoming.set(nextId, Math.max(0, (incoming.get(nextId) || 0) - 1));

      if ((incoming.get(nextId) || 0) === 0 && !seen.has(nextId)) {
        queue.push(nextNode);
      }
    }

    queue.sort(visualSort);
  }

  const remaining = nodes
    .filter((node) => !seen.has(String(node.id)))
    .sort(visualSort);

  return [...ordered, ...remaining];
}

const AION_WORKFLOW_GLYPH_NAMESPACE = "aion.workflow";

const AION_WORKFLOW_OPS = Object.freeze({
  SEQUENCE: "aion.workflow:sequence",
  TRIGGER: "aion.workflow:trigger",
  EXTRACT: "aion.workflow:extract",
  CLASSIFY: "aion.workflow:classify",
  ACTION: "aion.workflow:action",
  APPROVAL: "aion.workflow:approval",
  WAIT: "aion.workflow:wait",
  ROUTE: "aion.workflow:route",
});

function getAionWorkflowBusinessContainerId() {
  const fromWindow =
    window.__aionWorkspaceId ||
    window.__aionBusinessContainerId ||
    window.__aionWorkflowBusinessContainerId;

  const fromState =
    desktopStore?.state?.workspaceId ||
    desktopStore?.state?.workspace_id ||
    desktopStore?.state?.businessContainerId ||
    desktopStore?.state?.business_container;

  return String(fromWindow || fromState || "costa_conexion")
    .trim()
    .replace(/[^a-zA-Z0-9_-]/g, "_")
    || "costa_conexion";
}

function normaliseAionWorkflowNodeToGlyphStep(node, index = 0) {
  const title = String(node?.title || "").toLowerCase();
  const type = String(node?.type || "").toLowerCase();
  const id = String(node?.id || `node_${index}`);

  let op = AION_WORKFLOW_OPS.ACTION;

  if (
    type.includes("trigger") ||
    title.includes("trigger") ||
    title.includes("gmail new email") ||
    title.includes("schedule") ||
    title.includes("webhook")
  ) {
    op = AION_WORKFLOW_OPS.TRIGGER;
  } else if (
    title.includes("extract") ||
    title.includes("pattern") ||
    title.includes("replace") ||
    title.includes("html") ||
    title.includes("variable") ||
    title.includes("compose string") ||
    title.includes("sleep") ||
    title.includes("delay") ||
    type.includes("parser") ||
    type.includes("tools")
  ) {
    op = AION_WORKFLOW_OPS.EXTRACT;
  } else if (
    title.includes("classify") ||
    title.includes("router") ||
    title.includes("route")
  ) {
    op = AION_WORKFLOW_OPS.CLASSIFY;
  } else if (
    title.includes("approval") ||
    type.includes("gate")
  ) {
    op = AION_WORKFLOW_OPS.APPROVAL;
  } else if (
    title.includes("wait") ||
    title.includes("delay") ||
    title.includes("schedule")
  ) {
    op = AION_WORKFLOW_OPS.WAIT;
  } else if (
    title.includes("if") ||
    title.includes("else") ||
    title.includes("fork")
  ) {
    op = AION_WORKFLOW_OPS.ROUTE;
  }

  return {
    op,
    node_id: id,
    ref: id,
    title: String(node?.title || "Untitled step"),
    node_type: String(node?.type || "Action"),
    status: String(node?.status || "draft"),
    meta: String(node?.meta || ""),
    position: {
      x: Number(node?.x || 0),
      y: Number(node?.y || 0),
    },
    config: node?.config && typeof node.config === "object" ? node.config : {},
  };
}

function isAionWorkflowSyntheticChooseNode(node) {
  if (!node) return false;

  const id = String(node.id || "");
  const title = String(node.title || node.label || "").trim().toLowerCase();
  const actionId = String(node.action_id || node.action || node.config?.action_id || "").trim().toLowerCase();

  return (
    id === "node_choose_start" ||
    (
      title === "choose" &&
      (!actionId || actionId === "generic.step")
    )
  );
}

function orderAionWorkflowNodesForGlyph(graph) {
  const nodes = Array.isArray(graph?.nodes)
    ? graph.nodes.filter((node) => !isAionWorkflowSyntheticChooseNode(node))
    : [];

  const syntheticChooseIds = new Set(
    Array.isArray(graph?.nodes)
      ? graph.nodes
          .filter((node) => isAionWorkflowSyntheticChooseNode(node))
          .map((node) => String(node.id))
      : [],
  );

  const edges = Array.isArray(graph?.edges)
    ? graph.edges.filter((edge) => !syntheticChooseIds.has(String(edge?.from || "")))
    : [];

  if (!nodes.length) return [];

  const nodeById = new Map(nodes.map((node) => [String(node.id), node]));
  const incoming = new Map(nodes.map((node) => [String(node.id), 0]));
  const outgoing = new Map(nodes.map((node) => [String(node.id), []]));

  for (const edge of edges) {
    const from = String(edge?.from || "");
    const to = String(edge?.to || "");
    if (!nodeById.has(from) || !nodeById.has(to)) continue;
    incoming.set(to, (incoming.get(to) || 0) + 1);
    outgoing.get(from)?.push(to);
  }

  const queue = nodes
    .filter((node) => (incoming.get(String(node.id)) || 0) === 0)
    .sort((a, b) => Number(a.x || 0) - Number(b.x || 0));

  const ordered = [];
  const seen = new Set();

  while (queue.length) {
    const node = queue.shift();
    const id = String(node.id);
    if (seen.has(id)) continue;

    seen.add(id);
    ordered.push(node);

    const nextIds = (outgoing.get(id) || [])
      .filter((nextId) => !seen.has(nextId))
      .sort((a, b) => Number(nodeById.get(a)?.x || 0) - Number(nodeById.get(b)?.x || 0));

    for (const nextId of nextIds) {
      const nextIncoming = Math.max(0, (incoming.get(nextId) || 0) - 1);
      incoming.set(nextId, nextIncoming);
      if (nextIncoming === 0 && nodeById.has(nextId)) {
        queue.push(nodeById.get(nextId));
      }
    }
  }

  const remaining = nodes
    .filter((node) => !seen.has(String(node.id)))
    .sort((a, b) => Number(a.x || 0) - Number(b.x || 0));

  return [...ordered, ...remaining];
}

function collectAionWorkflowRequiredConnectors(graph) {
  const nodes = Array.isArray(graph?.nodes) ? graph.nodes : [];

  return Array.from(
    new Set(
      nodes
        .map((node) => {
          const config = node?.config && typeof node.config === "object" ? node.config : {};
          return String(config.connector || node.connector || config.app || "").trim();
        })
        .filter(Boolean)
        .filter((connector) => !["logic", "tools", "tool", "flow"].includes(connector.toLowerCase())),
    ),
  );
}

function collectAionWorkflowBoardroomEvents(graph) {
  const nodes = Array.isArray(graph?.nodes) ? graph.nodes : [];

  return Array.from(
    new Set(
      nodes.flatMap((node) => {
        const config = node?.config && typeof node.config === "object" ? node.config : {};
        const declared =
          config.boardroom_events ||
          config.boardroom_event ||
          config.events ||
          node.boardroom_events ||
          [];

        if (Array.isArray(declared)) return declared;
        if (typeof declared === "string") {
          return declared
            .split(",")
            .map((item) => item.trim())
            .filter(Boolean);
        }

        return [];
      }),
    ),
  );
}

function inferAionWorkflowRiskTier(graph) {
  const nodes = Array.isArray(graph?.nodes) ? graph.nodes : [];
  const hasExternalWrite = nodes.some((node) => {
    const config = node?.config && typeof node.config === "object" ? node.config : {};
    const action = String(config.action_id || config.module_id || node?.action_id || "").toLowerCase();

    return (
      config.external_write === true ||
      config.requires_approval === true ||
      action.includes("send") ||
      action.includes("publish") ||
      action.includes("create_draft") ||
      action.includes("post_social")
    );
  });

  return hasExternalWrite ? "medium" : "low";
}

function compileAionWorkflowGraphToGlyph(graph) {
  const safeGraph = graph && typeof graph === "object" ? graph : {};
  const orderedNodes = orderAionWorkflowNodesForGlyph(safeGraph);
  const steps = orderedNodes.map((node, index) =>
    normaliseAionWorkflowNodeToGlyphStep(node, index),
  );

  const syntheticChooseIds = new Set(
    Array.isArray(safeGraph.nodes)
      ? safeGraph.nodes
          .filter((node) => isAionWorkflowSyntheticChooseNode(node))
          .map((node) => String(node.id))
      : [],
  );

  const edges = Array.isArray(safeGraph.edges)
    ? safeGraph.edges
        .filter((edge) => !syntheticChooseIds.has(String(edge?.from || "")))
        .filter((edge) => !syntheticChooseIds.has(String(edge?.to || "")))
        .map((edge) => ({
          from: String(edge?.from || ""),
          to: String(edge?.to || ""),
          condition: String(edge?.condition || "success"),
        }))
    : [];

  const approvalPolicy = {
    dry_run_first: true,
    approval_before_external_write: true,
    raw_glyph_execution: false,
    raw_glyphs_are_ui_decoration_only: true,
  };

  return {
    schema_version: AION_WORKFLOW_GLYPH_SCHEMA_VERSION,
    namespace: AION_WORKFLOW_GLYPH_NAMESPACE,
    glyph_type: "workflow_capsule",
    callable: true,
    op: AION_WORKFLOW_OPS.SEQUENCE,
    workflow: {
      workflow_id: String(safeGraph.workflow_id || window.__aionCreateUniqueWorkflowId?.() || "workflow_draft"),
      name: String(safeGraph.name || "Untitled workflow 1"),
      business_container: String(
        safeGraph.business_container || getAionWorkflowBusinessContainerId(),
      ),
      status: String(safeGraph.status || "draft"),
    },
    inputs_schema:
      safeGraph.inputs_schema && typeof safeGraph.inputs_schema === "object"
        ? safeGraph.inputs_schema
        : {},
    outputs_schema:
      safeGraph.outputs_schema && typeof safeGraph.outputs_schema === "object"
        ? safeGraph.outputs_schema
        : {},
    required_connectors: collectAionWorkflowRequiredConnectors(safeGraph),
    approval_policy: approvalPolicy,
    risk_tier: String(safeGraph.risk_tier || inferAionWorkflowRiskTier(safeGraph) || "low"),
    boardroom_events: collectAionWorkflowBoardroomEvents(safeGraph),
    policy: approvalPolicy,
    steps,
    flow_links: edges,
    compiled_at: new Date().toISOString(),
  };
}

function compileAndAttachAionWorkflowGlyph(graph) {
  const target = graph || getAionWorkflowDraftState();
  target.business_container = target.business_container || getAionWorkflowBusinessContainerId();
  target.compiled_glyph = compileAionWorkflowGraphToGlyph(target);
  target.compiled_glyph_hash_hint = `${target.compiled_glyph.schema_version}:${target.workflow_id || window.__aionCreateUniqueWorkflowId?.() || "workflow_draft"}:${target.compiled_glyph.steps.length}:${target.compiled_glyph.flow_links.length}`;
  return target.compiled_glyph;
}


function getDefaultAionWorkflowDraftState() {
  return {
    workflow_id: createAionWorkflowId(),
    name: "Untitled workflow 1",
    status: "draft",
    nodes: [],
    edges: [],
    updated_at: new Date().toISOString(),
  };
}

function stripAionWorkflowSyntheticChooseNode(graph) {
  if (!graph || typeof graph !== "object") return graph;

  const nodes = Array.isArray(graph.nodes) ? graph.nodes : [];
  const syntheticIds = new Set(
    nodes
      .filter((node) =>
        typeof isAionWorkflowSyntheticChooseNode === "function" &&
        isAionWorkflowSyntheticChooseNode(node)
      )
      .map((node) => String(node.id)),
  );

  if (!syntheticIds.size) return graph;

  graph.nodes = nodes.filter((node) => !syntheticIds.has(String(node.id)));
  graph.edges = Array.isArray(graph.edges)
    ? graph.edges.filter(
        (edge) =>
          !syntheticIds.has(String(edge?.from || "")) &&
          !syntheticIds.has(String(edge?.to || "")),
      )
    : [];

  if (syntheticIds.has(String(window.__aionWorkflowSelectedNodeId || ""))) {
    window.__aionWorkflowSelectedNodeId = graph.nodes[0]?.id || null;
  }

  graph.updated_at = new Date().toISOString();
  graph.dirty = true;

  return graph;
}

function getAionWorkflowDraftState() {
  /*
   * CLEAN TAB GRAPH RESOLVER
   *
   * Main workflow and glyph workflow tabs must never share graph objects.
   * The renderer calls this function, so this is the single source of truth.
   */
  const activeTab = String(window.__aionActiveWorkflowTab || "").toLowerCase();
  const activeGlyphCode = String(
    window.__aionActiveGlyphWorkflowTabCode ||
    window.__aionActiveGlyphWorkflowCode ||
    ""
  ).trim();

  if (activeTab === "glyph" && activeGlyphCode && activeGlyphCode.toLowerCase() !== "main") {
    const store =
      window.__aionOpenedGlyphWorkflowGraphsByCode &&
      typeof window.__aionOpenedGlyphWorkflowGraphsByCode === "object"
        ? window.__aionOpenedGlyphWorkflowGraphsByCode
        : {};

    const glyphGraph =
      store[activeGlyphCode] ||
      store[activeGlyphCode.toUpperCase()] ||
      store[activeGlyphCode.toLowerCase()] ||
      window.__aionOpenedGlyphWorkflowGraph;

    if (glyphGraph && typeof glyphGraph === "object") {
      glyphGraph.glyph_code = glyphGraph.glyph_code || activeGlyphCode;
      window.__aionOpenedGlyphWorkflowGraph = glyphGraph;
      window.__aionWorkflowGraph = glyphGraph;
      return stripAionWorkflowSyntheticChooseNode(glyphGraph);
    }
  }

  if (
    window.__aionWorkflowMainGraph &&
    typeof window.__aionWorkflowMainGraph === "object"
  ) {
    window.__aionWorkflowGraph = window.__aionWorkflowMainGraph;
    return stripAionWorkflowSyntheticChooseNode(window.__aionWorkflowMainGraph);
  }

  if (window.__aionWorkflowGraph && typeof window.__aionWorkflowGraph === "object") {
    window.__aionWorkflowMainGraph = window.__aionWorkflowGraph;
    return stripAionWorkflowSyntheticChooseNode(window.__aionWorkflowGraph);
  }

  try {
    const raw = localStorage.getItem(AION_WORKFLOW_DRAFT_STORAGE_KEY);
    if (raw) {
      const parsed = JSON.parse(raw);
      window.__aionWorkflowMainGraph = stripAionWorkflowSyntheticChooseNode({
        ...getDefaultAionWorkflowDraftState(),
        ...parsed,
        nodes: Array.isArray(parsed.nodes) ? parsed.nodes : [],
        edges: Array.isArray(parsed.edges) ? parsed.edges : [],
      });
      window.__aionWorkflowGraph = window.__aionWorkflowMainGraph;
      return window.__aionWorkflowMainGraph;
    }
  } catch (error) {
    console.warn("[workflow] failed to load draft", error);
  }

  window.__aionWorkflowMainGraph = getDefaultAionWorkflowDraftState();
  window.__aionWorkflowGraph = window.__aionWorkflowMainGraph;
  return window.__aionWorkflowMainGraph;
}


function buildAionWorkflowSavePayload(graph) {
  const safeGraph = graph || getAionWorkflowDraftState();
  const compiledGlyph =
    safeGraph.compiled_glyph || compileAionWorkflowGraphToGlyph(safeGraph);

  const nodes = Array.isArray(safeGraph.nodes) ? safeGraph.nodes : [];
  const edges = Array.isArray(safeGraph.edges) ? safeGraph.edges : [];

  return {
    schema_version: "aion.workflow_save.v1",
    storage_scope: "business_container",
    business_container:
      compiledGlyph?.workflow?.business_container ||
      safeGraph.business_container ||
      "costa-conexion",
    workflow_id: safeGraph.workflow_id || window.__aionCreateUniqueWorkflowId?.() || "workflow_draft",
    name: safeGraph.name || "Untitled workflow 1",
    status: safeGraph.status || "draft",
    canvas_layout: {
      schema_version: "aion.workflow_canvas_layout.v1",
      coordinate_space: "absolute_canvas_px",
      nodes: nodes.map((node) => ({
        node_id: node.id,
        x: Number(node.x || 0),
        y: Number(node.y || 0),
      })),
      edges: edges.map((edge) => ({
        from: edge.from,
        to: edge.to,
        condition: edge.condition || "success",
      })),
    },
    graph: {
      nodes,
      edges,
    },
    compiled_glyph: compiledGlyph,
    saved_at: new Date().toISOString(),
  };
}

function getAionWorkflowPendingNodeConfig(nodeId) {
  window.__aionWorkflowPendingNodeConfig = window.__aionWorkflowPendingNodeConfig || {};
  return window.__aionWorkflowPendingNodeConfig[nodeId] || {};
}

function setAionWorkflowPendingNodeConfig(nodeId, key, value) {
  if (!nodeId || !key) return;

  window.__aionWorkflowPendingNodeConfig = window.__aionWorkflowPendingNodeConfig || {};
  window.__aionWorkflowPendingNodeConfig[nodeId] = {
    ...(window.__aionWorkflowPendingNodeConfig[nodeId] || {}),
    [key]: value,
  };
}

function applyAionWorkflowPendingNodeConfig(nodeId) {
  if (!nodeId) return null;

  const graph = getAionWorkflowDraftState();
  const nodes = Array.isArray(graph.nodes) ? graph.nodes : [];
  const pending = getAionWorkflowPendingNodeConfig(nodeId);
  const node = nodes.find((item) => item.id === nodeId);

  if (!node) return null;

  const config = {
    ...(node.config || {}),
    ...pending,
  };

  window.__aionWorkflowGraph = {
    ...graph,
    nodes: nodes.map((item) =>
      item.id === nodeId
        ? {
            ...item,
            config,
          }
        : item,
    ),
  };

  compileAndAttachAionWorkflowGlyph(window.__aionWorkflowGraph);
  persistAionWorkflowDraftState();

  return config;
}


function syncAionWorkflowInspectorInputsToGraph() {
  const graph = getAionWorkflowDraftState();
  const nodes = Array.isArray(graph.nodes) ? graph.nodes : [];

  document
    .querySelectorAll("[data-aion-workflow-node-config-input]")
    .forEach((input) => {
      const nodeId = input.getAttribute("data-aion-workflow-node-id");
      const key = input.getAttribute("data-aion-workflow-node-config-input");

      if (!nodeId || !key) return;

      const node = nodes.find((item) => item.id === nodeId);
      if (!node) return;

      node.config = {
        ...(node.config || {}),
        [key]: input.value,
      };
    });

  window["__aionWorkflowGraph"] = graph;
  compileAndAttachAionWorkflowGlyph(graph);

  return graph;
}


function persistAionWorkflowDraftState() {
  const activeTab = String(window.__aionActiveWorkflowTab || "").toLowerCase();
  const activeGlyphCode = String(
    window.__aionActiveGlyphWorkflowTabCode ||
    window.__aionActiveGlyphWorkflowCode ||
    ""
  ).trim();

  const graph =
    activeTab === "glyph" && window.__aionOpenedGlyphWorkflowGraph
      ? window.__aionOpenedGlyphWorkflowGraph
      : getAionWorkflowDraftState();

  const compactGraph = {
    ...graph,
    nodes: Array.isArray(graph.nodes) ? graph.nodes.map((node) => ({ ...node })) : [],
    edges: Array.isArray(graph.edges) ? graph.edges.map((edge) => ({ ...edge })) : [],
    updated_at: new Date().toISOString(),
  };

  if (activeTab === "glyph" && activeGlyphCode && activeGlyphCode.toLowerCase() !== "main") {
    compactGraph.glyph_code = compactGraph.glyph_code || activeGlyphCode;

    window.__aionOpenedGlyphWorkflowGraphsByCode =
      window.__aionOpenedGlyphWorkflowGraphsByCode &&
      typeof window.__aionOpenedGlyphWorkflowGraphsByCode === "object"
        ? window.__aionOpenedGlyphWorkflowGraphsByCode
        : {};

    window.__aionOpenedGlyphWorkflowGraphsByCode[activeGlyphCode] = compactGraph;
    window.__aionOpenedGlyphWorkflowGraph = compactGraph;
    window.__aionWorkflowGraph = compactGraph;
    return compactGraph;
  }

  window.__aionWorkflowMainGraph = compactGraph;
  window.__aionWorkflowGraph = compactGraph;

  try {
    localStorage.setItem(AION_WORKFLOW_DRAFT_STORAGE_KEY, JSON.stringify(compactGraph));
  } catch (error) {
    console.warn("[workflow] failed to save draft", error);
  }

  return compactGraph;
}




function markAionWorkflowDraftDirty(reason = "updated") {
  const graph = getAionWorkflowDraftState();
  graph.dirty = true;
  graph.dirty_reason = reason;
  graph.saved_at = graph.saved_at || null;
  compileAndAttachAionWorkflowGlyph(graph);
  window["__aionWorkflowGraph"] = graph;
  persistAionWorkflowDraftState();
  return graph;
}

function getAionWorkflowSaveStatus(graph) {
  const safeGraph = graph || getAionWorkflowDraftState();
  const compiled = safeGraph?.compiled_glyph || compileAionWorkflowGraphToGlyph(safeGraph);
  const dirty = Boolean(safeGraph?.dirty);
  const savedAt = safeGraph?.saved_at || null;

  if (dirty) {
    return {
      label: "Unsaved",
      className: "is-unsaved",
      detail: "Changes not saved",
    };
  }

  if (savedAt) {
    return {
      label: "Saved",
      className: "is-saved",
      detail: `Saved ${new Date(savedAt).toLocaleTimeString([], { hour: "2-digit", minute: "2-digit" })}`,
    };
  }

  return {
    label: "Draft",
    className: "is-draft",
    detail: "Local draft",
  };
}

async function loadAionWorkflowFromBusinessContainer({
  businessContainer = "costa-conexion",
  workflowId = createAionWorkflowId(),
} = {}) {
  const apiBase =
    state.apiBase ||
    state.desktopApiBase ||
    window.AION_API_BASE ||
    "http://127.0.0.1:8080";

  const safeBusiness = String(businessContainer || "costa-conexion").trim() || "costa-conexion";
  const safeWorkflowId = String(workflowId || window.__aionCreateUniqueWorkflowId?.() || "workflow_draft").trim() || window.__aionCreateUniqueWorkflowId?.() || "workflow_draft";

  const response = await fetch(
    `${apiBase}/api/aion/workflows/${encodeURIComponent(safeBusiness)}/${encodeURIComponent(safeWorkflowId)}`,
  );

  if (!response.ok) {
    throw new Error(`Workflow load failed: HTTP ${response.status}`);
  }

  const result = await response.json();
  if (!result?.ok || !result?.workflow) {
    throw new Error(result?.error || "Workflow not found");
  }

  const record = result.workflow;
  const graph = record.graph || {};

  const loadedGraph = {
    workflow_id: record.workflow_id || safeWorkflowId,
    name: record.name || "Untitled workflow 1",
    status: record.status || "draft",
    business_container: record.business_container || safeBusiness,
    nodes: Array.isArray(graph.nodes) ? graph.nodes : [],
    edges: Array.isArray(graph.edges) ? graph.edges : [],
    compiled_glyph: record.compiled_glyph || null,
    backend_saved_at: record.updated_at || "",
    backend_storage_path: record.path || "",
    dirty: false,
  };

  compileAndAttachAionWorkflowGlyph(loadedGraph);
  window.__aionWorkflowGraph = loadedGraph;
  persistAionWorkflowDraftState();

  return loadedGraph;
}

async function maybeLoadAionWorkflowFromBusinessContainerOnce() {
  if (window.__aionWorkflowBusinessLoadAttempted === true) return;
  window.__aionWorkflowBusinessLoadAttempted = true;

  try {
    const businessContainer =
      state.workspaceId ||
      window.__aionWorkflowGraph?.business_container ||
      "costa-conexion";

    const workflowId =
      window.__aionWorkflowGraph?.workflow_id ||
      "workflow_draft";

    const loadedGraph = await loadAionWorkflowFromBusinessContainer({
      businessContainer,
      workflowId,
    });

    window.__aionWorkflowLoadNotice = `Loaded saved workflow: ${loadedGraph.name || loadedGraph.workflow_id}`;

    if (window.__aionWorkflowLoadNoticeTimer) {
      window.clearTimeout(window.__aionWorkflowLoadNoticeTimer);
    }

    window.__aionWorkflowLoadNoticeTimer = window.setTimeout(() => {
      window.__aionWorkflowLoadNotice = "";
      window.__aionWorkflowLoadNoticeTimer = null;
      requestRender();
    }, 20000);

    safeAionDesktopPatch({
      message: window.__aionWorkflowLoadNotice,
      messageTone: "success",
    });

    requestRender();
  } catch (error) {
    console.info("[workflow] no saved business-container workflow loaded", error);
  }
}


async function saveAionWorkflowToBusinessContainer(graph) {
  const safeGraph = graph || getAionWorkflowDraftState();
  const compiledGlyph = safeGraph.compiled_glyph || compileAionWorkflowGraphToGlyph(safeGraph);
  const businessContainer =
    compiledGlyph?.workflow?.business_container ||
    safeGraph.business_container ||
    state.workspaceId ||
    "costa-conexion";

  const payload = {
    schema_version: "aion.workflow_save.v1",
    business_container: businessContainer,
    workflow_id: safeGraph.workflow_id || window.__aionCreateUniqueWorkflowId?.() || "workflow_draft",
    name: safeGraph.name || "Untitled workflow 1",
    status: safeGraph.status || "draft",
    graph: {
      nodes: Array.isArray(safeGraph.nodes) ? safeGraph.nodes : [],
      edges: Array.isArray(safeGraph.edges) ? safeGraph.edges : [],
    },
    compiled_glyph: compiledGlyph,
  };

  const apiBase =
    state.apiBase ||
    state.desktopApiBase ||
    window.AION_API_BASE ||
    "http://127.0.0.1:8080";

  const response = await fetch(`${apiBase}/api/aion/workflows/save`, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });

  if (!response.ok) {
    throw new Error(`Workflow save failed: HTTP ${response.status}`);
  }

  const result = await response.json();
  if (!result?.ok) {
    throw new Error(result?.error || "Workflow save failed");
  }

  safeGraph.business_container = result.business_container || businessContainer;
  safeGraph.backend_saved_at = result.updated_at || new Date().toISOString();
  safeGraph.backend_storage_path = result.path || "";

  compileAndAttachAionWorkflowGlyph(safeGraph);
  safeGraph.glyph_capsule_registry_item =
    upsertAionWorkflowGlyphCapsuleRegistryItem(safeGraph);

  return result;
}







const AION_WORKFLOW_GLYPH_CAPSULE_REGISTRY_KEY = "aion.workflow.glyph_capsules.v1";

function getAionWorkflowGlyphCapsuleRegistry() {
  try {
    const raw = window.localStorage?.getItem(AION_WORKFLOW_GLYPH_CAPSULE_REGISTRY_KEY);
    const parsed = raw ? JSON.parse(raw) : [];
    return Array.isArray(parsed) ? parsed : [];
  } catch {
    return [];
  }
}

function persistAionWorkflowGlyphCapsuleRegistry(items = []) {
  const safeItems = Array.isArray(items) ? items : [];
  try {
    window.localStorage?.setItem(
      AION_WORKFLOW_GLYPH_CAPSULE_REGISTRY_KEY,
      JSON.stringify(safeItems, null, 2),
    );
  } catch (error) {
    console.warn("[workflow] failed to persist glyph capsule registry", error);
  }
  return safeItems;
}

function upsertAionWorkflowGlyphCapsuleRegistryItem(graph) {
  const safeGraph = graph || getAionWorkflowDraftState();
  const compiledGlyph =
    safeGraph?.compiled_glyph || compileAionWorkflowGraphToGlyph(safeGraph);

  const workflowId =
    compiledGlyph?.workflow?.workflow_id ||
    safeGraph.workflow_id ||
    window.__aionCreateUniqueWorkflowId?.() ||
    "workflow_draft";

  const businessContainer =
    compiledGlyph?.workflow?.business_container ||
    safeGraph.business_container ||
    getAionWorkflowBusinessContainerId();

  const item = {
    id: `${businessContainer}:${workflowId}`,
    workflow_id: workflowId,
    name: compiledGlyph?.workflow?.name || safeGraph.name || "Untitled workflow 1",
    business_container: businessContainer,
    status: compiledGlyph?.workflow?.status || safeGraph.status || "draft",
    glyph_type: compiledGlyph?.glyph_type || "workflow_capsule",
    callable: compiledGlyph?.callable === true,
    risk_tier: compiledGlyph?.risk_tier || "low",
    required_connectors: Array.isArray(compiledGlyph?.required_connectors)
      ? compiledGlyph.required_connectors
      : [],
    boardroom_events: Array.isArray(compiledGlyph?.boardroom_events)
      ? compiledGlyph.boardroom_events
      : [],
    compiled_at: compiledGlyph?.compiled_at || new Date().toISOString(),
    saved_at: new Date().toISOString(),
    compiled_glyph: compiledGlyph,
  };

  const registry = getAionWorkflowGlyphCapsuleRegistry();
  const next = [
    item,
    ...registry.filter((existing) => String(existing?.id || "") !== item.id),
  ].slice(0, 100);

  persistAionWorkflowGlyphCapsuleRegistry(next);
  return item;
}

function listAionWorkflowGlyphCapsules() {
  return getAionWorkflowGlyphCapsuleRegistry();
}


function getAionWorkflowGlyphLibraryBusinessContainer() {
  const graph =
    typeof getAionWorkflowDraftState === "function"
      ? getAionWorkflowDraftState()
      : window.__aionWorkflowGraph || {};

  return String(
    graph?.business_container ||
    graph?.compiled_glyph?.workflow?.business_container ||
    "costa-conexion"
  );
}

function normaliseAionWorkflowGlyphLibraryItem(item = {}) {
  const compiled = item.compiled_glyph || {};
  const workflow = compiled.workflow || {};

  return {
    id: String(item.id || item.workflow_id || workflow.workflow_id || "workflow_glyph"),
    workflow_id: String(item.workflow_id || workflow.workflow_id || item.id || "workflow_glyph"),
    name: String(item.name || item.title || workflow.name || "Untitled workflow glyph"),
    business_container: String(item.business_container || workflow.business_container || "costa-conexion"),
    status: String(item.status || workflow.status || "draft"),
    glyph_type: String(item.glyph_type || compiled.glyph_type || "workflow_capsule"),
    callable: item.callable === true || compiled.callable === true,
    risk_tier: String(item.risk_tier || compiled.risk_tier || "low"),
    required_connectors: Array.isArray(item.required_connectors)
      ? item.required_connectors
      : Array.isArray(compiled.required_connectors)
        ? compiled.required_connectors
        : [],
    inputs_schema: item.inputs_schema || compiled.inputs_schema || {},
    outputs_schema: item.outputs_schema || compiled.outputs_schema || {},
    saved_at: String(item.saved_at || item.updated_at || item.compiled_at || ""),
  };
}

function listAionWorkflowGlyphLibraryItems() {
  const businessContainer = getAionWorkflowGlyphLibraryBusinessContainer();

  return listAionWorkflowGlyphCapsules()
    .map((item) => normaliseAionWorkflowGlyphLibraryItem(item))
    .filter((item) => item.business_container === businessContainer)
    .sort((a, b) => String(b.saved_at || "").localeCompare(String(a.saved_at || "")));
}

function summariseAionWorkflowGlyphSchema(schema = {}) {
  if (!schema || typeof schema !== "object") return "—";

  const properties =
    schema.properties && typeof schema.properties === "object"
      ? Object.keys(schema.properties)
      : Object.keys(schema);

  return properties.length ? properties.slice(0, 6).join(", ") : "Any payload";
}


function listAionMasterGlyphCanvasItems() {
  if (typeof listAionWorkflowGlyphLibraryItems === "function") {
    return listAionWorkflowGlyphLibraryItems()
      .filter((item) => item && item.callable === true);
  }

  if (typeof listAionWorkflowGlyphCapsules === "function") {
    return listAionWorkflowGlyphCapsules()
      .filter((item) => item && item.callable === true);
  }

  return [];
}

function summariseAionMasterGlyphValue(value, fallback = "None declared") {
  if (Array.isArray(value)) {
    if (!value.length) return fallback;
    return value
      .map((item) => {
        if (typeof item === "string") return item;
        return item?.event_type || item?.name || item?.connector || item?.id || JSON.stringify(item);
      })
      .filter(Boolean)
      .join(", ");
  }

  if (value && typeof value === "object") {
    const keys = Object.keys(value);
    return keys.length ? keys.slice(0, 6).join(", ") : fallback;
  }

  const text = String(value || "").trim();
  return text || fallback;
}

function renderAionMasterGlyphCanvasNode(item, index = 0) {
  const compiled = item?.compiled_glyph || {};
  const workflowId =
    item?.workflow_id ||
    compiled?.workflow?.workflow_id ||
    item?.id ||
    `glyph_${index + 1}`;

  const name =
    item?.name ||
    compiled?.workflow?.name ||
    workflowId ||
    "Untitled workflow glyph";

  const requiredConnectors =
    item?.required_connectors ||
    compiled?.required_connectors ||
    [];

  const boardroomEvents =
    item?.boardroom_events ||
    compiled?.boardroom_events ||
    [];

  const inputsSchema =
    item?.inputs_schema ||
    compiled?.inputs_schema ||
    {};

  const outputsSchema =
    item?.outputs_schema ||
    compiled?.outputs_schema ||
    {};

  return `
    <article
      class="aion-master-glyph-node"
      data-aion-master-glyph-node="true"
      data-workflow-id="${escapeHtml(workflowId)}"
      style="--glyph-x:${120 + (index % 3) * 340}px; --glyph-y:${120 + Math.floor(index / 3) * 260}px;"
    >
      <div class="aion-master-glyph-node-top">
        <span class="aion-master-glyph-orb">⬢</span>
        <div>
          <strong>${escapeHtml(name)}</strong>
          <small>${escapeHtml(workflowId)}</small>
        </div>
      </div>

      <div class="aion-master-glyph-meta-grid">
        <span>Status</span>
        <b>${escapeHtml(item?.status || compiled?.workflow?.status || "draft")}</b>

        <span>Callable</span>
        <b>${item?.callable === true || compiled?.callable === true ? "true" : "false"}</b>

        <span>Risk</span>
        <b>${escapeHtml(item?.risk_tier || compiled?.risk_tier || "low")}</b>

        <span>Connectors</span>
        <b>${escapeHtml(summariseAionMasterGlyphValue(requiredConnectors))}</b>

        <span>Inputs</span>
        <b>${escapeHtml(summariseAionMasterGlyphValue(inputsSchema, "Any payload"))}</b>

        <span>Outputs</span>
        <b>${escapeHtml(summariseAionMasterGlyphValue(outputsSchema, "Dry-run payload"))}</b>

        <span>Events</span>
        <b>${escapeHtml(summariseAionMasterGlyphValue(boardroomEvents))}</b>
      </div>

      <div class="aion-master-glyph-readonly-note">
        Master glyph source · no execution · saved glyph not mutated
      </div>

      <button
        type="button"
        class="secondary-btn secondary-btn-small"
        data-aion-master-glyph-stage-to-canvas="true"
        data-workflow-id="${escapeHtml(workflowId)}"
        title="Stage this callable glyph as a dry-run call_workflow_glyph node"
      >
        Stage to workflow canvas
      </button>
    </article>
  `;
}

function renderAionMasterGlyphCanvasPanel() {
  /*
   * RETIRED:
   * There is no separate Master Glyph Canvas surface anymore.
   * Reusable glyph workflows now live inside the normal Workflow Canvas via:
   * - Glyph Library button
   * - top workflow tabs
   * - staged/opened call_workflow_glyph nodes
   */
  return "";
}

function installAionMasterGlyphCanvasControls() {
  if (window.__aionMasterGlyphCanvasControlsInstalled === true) return;
  window.__aionMasterGlyphCanvasControlsInstalled = true;

  function cloneMasterGlyphValue(value) {
    try {
      return JSON.parse(JSON.stringify(value));
    } catch (_) {
      return value;
    }
  }

  function getCurrentWorkflowGraphForMasterGlyphStage() {
    if (typeof getAionWorkflowDraftState === "function") {
      try {
        const graph = getAionWorkflowDraftState();
        if (graph && typeof graph === "object") return graph;
      } catch (_) {}
    }

    window["__aionWorkflowGraph"] = window["__aionWorkflowGraph"] || {
      workflow_id: `workflow_${Date.now()}`,
      name: "Untitled workflow",
      status: "draft",
      nodes: [],
      edges: [],
    };

    return window["__aionWorkflowGraph"];
  }

  function findMasterGlyphCanvasItem(workflowId) {
    const needle = String(workflowId || "").trim().toLowerCase();
    if (!needle) return null;

    const items = typeof listAionMasterGlyphCanvasItems === "function"
      ? listAionMasterGlyphCanvasItems()
      : [];

    return items.find((item) => {
      const compiled = item?.compiled_glyph || {};
      return [
        item?.workflow_id,
        item?.id,
        item?.name,
        compiled?.workflow?.workflow_id,
        compiled?.workflow?.name,
      ].some((value) => String(value || "").trim().toLowerCase() === needle);
    }) || null;
  }

  function stageMasterGlyphToWorkflowCanvas(workflowId) {
    const item = findMasterGlyphCanvasItem(workflowId);
    if (!item) {
      if (typeof safePatchMessage === "function") {
        safePatchMessage("Could not find callable workflow glyph to stage.", "error");
      }
      return null;
    }

    const compiled = cloneMasterGlyphValue(item.compiled_glyph || {});
    const childWorkflowId =
      item.workflow_id ||
      compiled?.workflow?.workflow_id ||
      item.id ||
      workflowId;

    const graph = getCurrentWorkflowGraphForMasterGlyphStage();
    graph.nodes = Array.isArray(graph.nodes) ? graph.nodes : [];
    graph.edges = Array.isArray(graph.edges) ? graph.edges : [];

    const nodeId = `call_workflow_glyph_${Date.now()}_${Math.random().toString(16).slice(2, 8)}`;
    const x = 220 + (graph.nodes.length % 4) * 280;
    const y = 260 + Math.floor(graph.nodes.length / 4) * 180;

    const stagedNode = {
      id: nodeId,
      title: `Call ${item.name || compiled?.workflow?.name || childWorkflowId}`,
      label: `Call ${item.name || compiled?.workflow?.name || childWorkflowId}`,
      type: "Workflow Glyph",
      icon: "⌁",
      status: "Staged",
      meta: "Staged from Workflow Glyph Library · dry-run only · no execution yet",
      tone: "violet",
      x,
      y,
      dry_run_only: true,
      live_send_enabled: false,
      action_id: "call_workflow_glyph",
      module_id: "workflow.call_workflow_glyph",
      config: {
        action_id: "call_workflow_glyph",
        module_id: "workflow.call_workflow_glyph",
        workflow_id: childWorkflowId,
        child_workflow_id: childWorkflowId,
        glyph_id: item.id || childWorkflowId,
        callable: true,
        dry_run_only: true,
        live_send_enabled: false,
        risk_tier: item.risk_tier || compiled.risk_tier || "low",
        required_connectors: cloneMasterGlyphValue(item.required_connectors || compiled.required_connectors || []),
        inputs_schema: cloneMasterGlyphValue(item.inputs_schema || compiled.inputs_schema || {}),
        outputs_schema: cloneMasterGlyphValue(item.outputs_schema || compiled.outputs_schema || {}),
        approval_policy: cloneMasterGlyphValue(item.approval_policy || compiled.approval_policy || {}),
        boardroom_events: cloneMasterGlyphValue(item.boardroom_events || compiled.boardroom_events || []),
        compiled_glyph: compiled,
      },
      runtime: {
        input_items: [],
        output_items: [],
        execution_status: "idle",
        last_run_at: null,
        error: null,
      },
    };

    graph.nodes.push(stagedNode);
    graph.dirty = true;
    graph.updated_at = new Date().toISOString();

    window["__aionWorkflowGraph"] = graph;
    window.__aionWorkflowSelectedNodeId = nodeId;

    try {
      if (typeof compileAndAttachAionWorkflowGlyph === "function") {
        compileAndAttachAionWorkflowGlyph(graph);
      }
    } catch (_) {}

    try {
      if (typeof persistAionWorkflowDraftState === "function") {
        persistAionWorkflowDraftState();
      }
    } catch (_) {}

    if (typeof safePatchMessage === "function") {
      safePatchMessage(`Staged workflow glyph: ${item.name || childWorkflowId}`, "success");
    }

    if (typeof requestRender === "function") requestRender();

    return stagedNode;
  }

  window.__stageAionMasterGlyphToWorkflowCanvas = stageMasterGlyphToWorkflowCanvas;

  document.addEventListener("click", (event) => {
    const open = event.target.closest?.("[data-aion-master-glyph-canvas-open='true']");
    if (open) {
      event.preventDefault();
      event.stopPropagation();
      window.__aionMasterGlyphCanvasOpen = false;

      if (typeof window.__openAionWorkflowGlyphLibrary === "function") {
        window.__openAionWorkflowGlyphLibrary();
      } else if (typeof window.__openAionBackendGlyphLibraryModal === "function") {
        window.__openAionBackendGlyphLibraryModal();
      } else if (typeof window.__renderAionWorkflowGlyphLibraryModal === "function") {
        window.__renderAionWorkflowGlyphLibraryModal();
      }

      if (typeof requestRender === "function") requestRender();
      return;
    }

    const close = event.target.closest?.("[data-aion-master-glyph-canvas-close='true']");
    if (close) {
      event.preventDefault();
      event.stopPropagation();
      window.__aionMasterGlyphCanvasOpen = false;
      if (typeof requestRender === "function") requestRender();
      return;
    }

    const stage = event.target.closest?.("[data-aion-master-glyph-stage-to-canvas='true']");
    if (stage) {
      event.preventDefault();
      event.stopPropagation();
      stageMasterGlyphToWorkflowCanvas(stage.getAttribute("data-workflow-id"));
      return;
    }
  }, true);
}


